{
  "service": "user-service",
  "action": "get_user",
  "componentType": "rest",
  "description": "Fetch user by ID from upstream API",
  "config": {
    "uri": "https://jsonplaceholder.typicode.com/users/{{id}}",
    "method": "GET"
  }
}

{
  "service": "order-service",
  "action": "create_order",
  "componentType": "rest",
  "description": "Create order in upstream system with auth, retry, and response mapping",
  "config": {
    "uri": "https://api.example.com/orders",
    "method": "POST",
    "contentType": "application/json",
    "headers": {
      "X-Tenant-Id": "acme-corp"
    },
    "timeout": {
      "connect": 5000,
      "response": 30000
    },
    "resilience": {
      "retryCount": 3,
      "retryDelay": 1000,
      "backoff": "exponential",
      "retryOn": [502, 503, 504]
    },
    "auth": {
      "oauth2": {
        "clientId": "$env.ORDER_API_CLIENT_ID",
        "clientSecret": "$env.ORDER_API_CLIENT_SECRET",
        "accessTokenUri": "https://auth.example.com/oauth/token",
        "scope": "orders:write"
      }
    },
    "payloadTemplate": {
      "customerId": "$.context.customerId",
      "items": "$.context.items",
      "totalAmount": "$.context.totalAmount"
    },
    "response": {
      "transformation": {
        "orderId": "$.id",
        "status": "$.status",
        "createdAt": "$.created_at"
      }
    }
  },
  "metaData": {
    "owner": "platform-team",
    "slack": "#orders-alerts"
  }
}

{
  "service": "order-service",
  "action": "create_order",
  "componentType": "rest",
  "description": "Updated: increased timeout and added circuit breaker",
  "config": {
    "uri": "https://api.example.com/orders",
    "method": "POST",
    "contentType": "application/json",
    "timeout": {
      "connect": 5000,
      "response": 60000
    },
    "resilience": {
      "retryCount": 3,
      "retryDelay": 1000,
      "backoff": "exponential",
      "retryOn": [502, 503, 504],
      "circuitBreaker": {
        "failureThreshold": 5,
        "windowSize": 60000,
        "openDuration": 30000,
        "halfOpenMaxAttempts": 3
      }
    },
    "auth": {
      "oauth2": {
        "clientId": "$env.ORDER_API_CLIENT_ID",
        "clientSecret": "$env.ORDER_API_CLIENT_SECRET",
        "accessTokenUri": "https://auth.example.com/oauth/token",
        "scope": "orders:write"
      }
    },
    "payloadTemplate": {
      "customerId": "$.context.customerId",
      "items": "$.context.items",
      "totalAmount": "$.context.totalAmount"
    },
    "response": {
      "transformation": {
        "orderId": "$.id",
        "status": "$.status",
        "createdAt": "$.created_at"
      }
    }
  }
}
